mapper.update:
update prompt_template
set template_name = #{templateName},
    content = #{content},
    variable_spec_json = #{variableSpecJson},
    updated_by = #{updatedBy},
    updated_at = #{updatedAt}
where id = #{id}
  and org_id = #{orgId}
  and state = 'DRAFT'

mapper.select:
select count(1)
from prompt_template
where (
    scope = 'GLOBAL'
    or org_id = #{orgId}
)

    and scope = #{scope}


    and state = #{state}


    and (
        template_code like concat('%', #{keyword}, '%')
        or template_name like concat('%', #{keyword}, '%')
    )

select id, scope, org_id, template_code, template_name, version_no, state, content, variable_spec_json, created_by, updated_by, created_at, updated_at from prompt_template where ( scope = 'GLOBAL' or org_id = #{orgId} )
and scope = #{scope}
and state = #{state}
and ( template_code like concat('%', #{keyword}, '%') or template_name like concat('%', #{keyword}, '%') )
order by scope asc, updated_at desc, id desc limit #{pageSize} offset #{offset}

select count(1)
from prompt_template
where org_id = #{orgId}
  and template_code = #{templateCode}
